export type Language = 'en' | 'ru';
export type TranslationKey = keyof typeof translations;

const DEFAULT_LANGUAGE: Language = 'ru';
const PRIMARY_LANGUAGE_STORAGE_KEY = 'preferred-language';
const LEGACY_LANGUAGE_STORAGE_KEY = 'language';

const resolveStoredLanguage = (): Language => {
  if (typeof window === 'undefined') {
    return DEFAULT_LANGUAGE;
  }

  const storage = window.localStorage;
  if (!storage) {
    return DEFAULT_LANGUAGE;
  }

  const storedLanguage =
    storage.getItem(PRIMARY_LANGUAGE_STORAGE_KEY) ??
    storage.getItem(LEGACY_LANGUAGE_STORAGE_KEY);

  return storedLanguage === 'en' || storedLanguage === 'ru'
    ? storedLanguage
    : DEFAULT_LANGUAGE;
};

const persistLanguage = (language: Language) => {
  if (typeof window === 'undefined') {
    return;
  }

  const storage = window.localStorage;
  if (!storage) {
    return;
  }

  storage.setItem(PRIMARY_LANGUAGE_STORAGE_KEY, language);
  storage.setItem(LEGACY_LANGUAGE_STORAGE_KEY, language);
};

const applyDocumentLanguage = (language: Language) => {
  if (typeof document !== 'undefined') {
    document.documentElement.lang = language;
  }
};

class I18nService {
  private currentLanguage: Language = DEFAULT_LANGUAGE;
  private listeners: Array<(lang: Language) => void> = [];

  constructor() {
    this.currentLanguage = resolveStoredLanguage();
  }

  getCurrentLanguage(): Language {
    return this.currentLanguage;
  }

  setLanguage(lang: Language): void {
    this.currentLanguage = lang;
    persistLanguage(lang);
    applyDocumentLanguage(lang);
    this.listeners.forEach(callback => callback(lang));
  }

  subscribe(callback: (lang: Language) => void): () => void {
    this.listeners.push(callback);
    return () => {
      this.listeners = this.listeners.filter(listener => listener !== callback);
    };
  }

  t(key: TranslationKey, params?: Record<string, string | number>): string {
    const translation = translations[key];
    if (!translation) {
      devLog(`Translation missing for key: ${key}`);
      return key.toString();
    }
    let text: string = translation[this.currentLanguage] || translation['en'] || key.toString();
    if (params) {
      for (const [paramKey, paramValue] of Object.entries(params)) {
        text = text.split(`{${paramKey}}`).join(String(paramValue));
      }
    }
    return text;
  }
}

export const i18n = new I18nService();

applyDocumentLanguage(i18n.getCurrentLanguage());
